1254	+import type { ObjectiveRules } from "@pirate-sea-race/simulation/objectives";
1255	+import { MATCH_PRESET } from "./objectives.js";
1256	+
1257	+/**
1258	+ * The match flow's configs (§2, §5), built from one set of rules so they cannot disagree: the match module's timer
1259	+ * runs for exactly the claim rules' `deadlineTicks` (the claim deadline and the 35:00 timer are one number), its
1260	+ * departure lasts exactly the encounter rules' spawn protection, and its starting gold is the ledger's.
1261	+ */
1262	+export interface FlowRules {
1263	+  /** §2's lobby and ready check. `departureTicks` is ignored: the departure is the encounter rules' spawn protection. */
1264	+  readonly match: MatchRules;
1265	+  /** §5's channel, circle and §2's deadline. */
1266	+  readonly claim: ClaimRules;
1267	+  /** §2's minute-20 and minute-28 reveals. */
1268	+  readonly intel: IntelRules;
1269	+  readonly encounters: EncounterRules;
1270	+  readonly objectives: ObjectiveRules;
1271	+}
1272	+
1273	+/**
1274	+ * The lobby-to-results config of a private match. The private minimum is the match module's (`PRIVATE_MIN_PLAYERS`,
1275	+ * 2): the content's older `privateMatch.minPlayers` (1) is stale and not read.
1276	+ */
1277	+export function matchConfigFor(rules: FlowRules): MatchConfig {
1278	+  return createMatchConfig({
1279	+    kind: "private",
1280	+    rules: { ...rules.match, departureTicks: rules.encounters.spawnProtectionTicks },
1281	+    durationTicks: rules.claim.deadlineTicks,
1282	+    startingGold: rules.objectives.startingGold,
1283	+  });
1284	+}
1285	+
1286	+/** The claim config once player control starts on `controlStartTick`: its deadline is the timer's end. */
1287	+export function claimConfigFor(rules: FlowRules, claimPoint: ClaimPoint, controlStartTick: number, map: SeaMapDefinition): ClaimConfig {
1288	+  return createClaimConfig({ claimPoint, controlStartTick, rules: rules.claim, subUnitsPerTile: map.subUnitsPerTile });
1289	+}
1290	+
1291	+/** The intel config once player control starts: the reveals count from `controlStartTick`. */
1292	+export function intelConfigFor(rules: FlowRules, claimPoint: ClaimPoint, controlStartTick: number, map: SeaMapDefinition): IntelConfig {
1293	+  return createIntelConfig({ preset: MATCH_PRESET, finalIsland: claimPoint, controlStartTick, map, rules: rules.intel });
1294	+}
1295	+
1296	+/** The final island (§3, §5): the socket a secret picks, and its claim point, the centre of its claim tile. */
1297	+export function finalIslandOf(map: SeaMapDefinition, secret: number): { readonly socket: number; readonly claimPoint: ClaimPoint } {
1298	+  const socket = chooseFinalSocket(map, secret);
1299	+  const tile = map.finalSockets[socket]!.claimTile;
1300	+  const half = Math.floor(map.subUnitsPerTile / 2);
1301	+  return { socket, claimPoint: { x: tile.tileX * map.subUnitsPerTile + half, y: tile.tileY * map.subUnitsPerTile + half } };
1302	+}
