1363	@@ -0,0 +1,33 @@
1364	+import { createHmac, randomBytes } from "node:crypto";
1365	+
1366	+/**
1367	+ * A match's seeds (§3, §16). The room draws one private master secret per match from `node:crypto` and derives an
1368	+ * independent 32-bit seed for each system from it with a keyed hash: HMAC-SHA-256 keyed by the secret over
1369	+ * `SEED_LABEL` and the system's name, of which the first four bytes (big-endian) are the seed. So no system's seed
1370	+ * says anything about another's, none is ever passed raw to two systems, and none depends on the public match code,
1371	+ * which the derivation never reads.
1372	+ */
1373	+
1374	+/** Bytes in a master secret: 256 bits. */
1375	+export const MASTER_SECRET_BYTES = 32;
1376	+
1377	+/** The versioned label every derivation hashes before the system's name. */
1378	+export const SEED_LABEL = "pirate-sea-race/seed/v1/";
1379	+
1380	+/**
1381	+ * The systems that draw a seed. `world` seeds the simulation state, `ledger` the rubbings' deal onto the sources,
1382	+ * `final-socket` the final island's socket, `intel` the intel module's draws; `ruins` and `fruit` are reserved for the
1383	+ * ruins' puzzles and the fruit deal. Each duel at sea draws `duel:<n>`, its n-th duel.
1384	+ */
1385	+export type SeedSystem = "world" | "ledger" | "final-socket" | "intel" | "ruins" | "fruit" | `duel:${number}`;
1386	+
1387	+/** A fresh master secret from `node:crypto`: the production source. */
1388	+export function drawMasterSecret(): Uint8Array {
1389	+  return new Uint8Array(randomBytes(MASTER_SECRET_BYTES));
1390	+}
1391	+
1392	+/** The seed of one system: HMAC-SHA-256(secret, SEED_LABEL + system), its first four bytes as an unsigned integer. */
1393	+export function deriveSeed(secret: Uint8Array, system: SeedSystem): number {
1394	+  if (secret.length < 16) throw new RangeError(`a master secret needs at least 16 bytes, got ${secret.length}`);
1395	+  return createHmac("sha256", secret).update(SEED_LABEL + system, "utf8").digest().readUInt32BE(0);
1396	+}
