497	   * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
498	   * carrying the creator's token, then only seats carrying this match's code. Throwing refuses and frees the seat.
499	   */
500	  override onJoin(client: Client, options: unknown): void {
501	    this.admit(options);
502	    // §2: a match that has left its lobby takes no one new, whatever path the request took.
503	    if (this.flow.phase !== "lobby") throw new ServerError(JoinRefusal.MatchFull, MATCH_STARTED_MESSAGE);
504	    this.flowReports.push({ kind: "join", playerId: client.sessionId });
505	    this.simulation = addShip(this.config, this.simulation, client.sessionId);
506	    this.ledgerStep("addPlayer", addPlayer(this.ledger, { playerId: client.sessionId, tick: this.simulation.worldTick }));
507	    this.gates.set(client.sessionId, new InputGate());
508	    client.view = new StateView();
509	    this.mirror();
510	  }
511	
512	  /**
513	   * A player's connection dropped without leaving (§12). The ledger marks them disconnected at once (their hold is
514	   * cancelled and their seat reserved until its deadline); the ship stays in the world and can be grappled. A fighter
515	   * in an unfinished duel is marked away, the fight going on with their input substituted, and forfeits if still away
516	   * after `duelAbsenceTicks`. Colyseus keeps the socket's seat for the outer bound only.
517	   */
518	  override onDrop(client: Client): void {
519	    const id = client.sessionId;
520	    // A request refused in onJoin (a wrong code, a used token) still drops and leaves, but never became a player.
521	    if (findPlayer(this.ledger, id) === undefined) return;
522	    const tick = this.simulation.worldTick;
523	    this.ledgerStep("disconnectPlayer", disconnectPlayer(this.ledger, { playerId: id, tick }));
524	    const duel = this.duelOfSession(id);
525	    const fighting = duel !== undefined && duel.machine.outcome === undefined;
526	    if (fighting) duel.machine.drop(id);
527	    const reconnection = this.allowReconnection(client, this.tuning.reconnectionSeconds);
528	    reconnection.catch(() => undefined);
529	    this.away.set(id, { reconnection, duelAbsentSince: fighting ? tick : undefined });
530	  }
531	
532	  /** The same player is back before the deadline: the same identity, view, ship and rubbings; a fighter resumes. */
533	  override onReconnect(client: Client): void {
534	    const id = client.sessionId;
535	    this.away.delete(id);
536	    this.ledgerStep("reconnectPlayer", reconnectPlayer(this.ledger, { playerId: id, tick: this.simulation.worldTick }));
537	    this.duelOfSession(id)?.machine.reconnect(id);
538	  }
539	
540	  /**
541	   * A player is gone for good. Unless the reservation already expired (the world tick removed them), this is a quit:
542	   * a consented leave, or Colyseus' outer bound closing first. The ledger forfeits a duel in progress and sends the
543	   * rest of their rubbings into a cache at the dock nearest their ship by sea; then the ship leaves.
544	   */
545	  override onLeave(client: Client): void {
546	    const id = client.sessionId;
547	    const player = findPlayer(this.ledger, id);
548	    if (player !== undefined && player.status !== "left") {
549	      this.quit(id);
550	      this.flowReports.push({ kind: "leave", playerId: id });
551	    }
552	    this.removePlayer(id);
