+    it("sends one choose-theft for a held key: the window's handler ignores its auto-repeat", () => {
+      const page = new EventTarget();
+      const sent: { duel: string; type: string }[] = [];
+      const theft = theftChooser(() => ({ objectives: { ...base, theftDuel: "d4", theftOptions: ["sun", "moon"], theftDeadline: 200 }, worldTick: 130 }), (message) => void sent.push({ ...message }));
+      page.addEventListener("keydown", (event) => theft.keydown(event as KeyboardEvent));
+      const press = (repeat: boolean) => {
+        const event = Object.assign(new Event("keydown", { cancelable: true }), { code: "Digit2", repeat });
+        page.dispatchEvent(event);
+        return event.defaultPrevented;
+      };
+      // The press sends its pick (and takes the key); the auto-repeats of the held key send nothing more.
+      expect(press(false)).toBe(true);
+      expect(press(true)).toBe(false);
