1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { claimRules } from "@pirate-sea-race/content/claim";
3	import { startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
4	import type { HeadlessClient, ResultLineView } from "@pirate-sea-race/test-tools";
5	import { GUEST_SEAT, HOST_SEAT, ledgerOf, placePair } from "./rubbingsSetup.js";
6	import { CLAIM_SEAT, flowTuning } from "./matchFlowSetup.js";
7	import { brawler, collectAt, dockFor, EAST, grapple, HOLD_E, HUB_X, OPEN_ROW, playersAt, resultOf, tracker, until } from "./seaDuelSetup.js";
8	
9	/**
10	 * §2's results columns that need a settled draw and a recovery cache, through the real room: a quitter leaves a
11	 * Moon in a cache at Palm Key, the host and the guest fight the mirrored duel to a double KO, then the host
12	 * collects Palm Key's Sun, claims the cache's Moon and wins by a claim. With `endings.test.ts`, every one of the
13	 * nine accomplishment columns is non-zero for some player in some ending. The mirrored fight needs both fighters'
14	 * inputs on time, so this file runs with the harness files, alone. Test-only timings: a two-second channel.
15	 */
16	const CHANNEL = 40;
17	let server: RunningGameServer;
18	let endpoint: string;
19	
20	beforeAll(async () => {
21	  const matchTuning = flowTuning({ claim: { ...claimRules, channelTicks: CHANNEL } });
22	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning });
23	  endpoint = `http://127.0.0.1:${server.port}`;
24	});
25	
26	afterAll(async () => {
27	  await server.close();
28	});
29	
30	/** A results line with nothing accomplished: the starting gold, and `seat` as given. */
31	const line = (seat: number, change: Partial<ResultLineView> = {}): ResultLineView => ({
32	  seat,
33	  winner: false,
34	  left: false,
35	  rubbingsHeld: 0,
36	  collected: 0,
37	  thefts: 0,
38	  lost: 0,
39	  duelsWon: 0,
40	  duelsLost: 0,
41	  duelsDrawn: 0,
42	  gold: 50,
43	  cachesClaimed: 0,
44	  islandsVisited: 0,
45	  ...change,
46	});
47	
48	describe("the results of a draw and a cache claim (§2, §12)", () => {
49	  it("counts a settled draw for both fighters and a cache claim for its claimer, and ends by a claim", async ({ onTestFinished }) => {
50	    const track = tracker(onTestFinished);
51	    const palmKey = dockFor("sun");
52	    const [host, guest, quitter] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT, { tileX: HUB_X - 6, tileY: OPEN_ROW + 4, heading: EAST }], track)) as [
53	      HeadlessClient,
54	      HeadlessClient,
55	      HeadlessClient,
56	    ];
57	    const seats = { host: host.seat, guest: guest.seat, quitter: quitter.seat };
58	
59	    // The quitter collects a Moon at Ember Rock, sails to Palm Key's west dock and quits: a cache with the Moon there.
60	    await collectAt(quitter, endpoint, dockFor("moon"), "moon");
61	    await quitter.placeShip(endpoint, { tileX: palmKey.tileX, tileY: palmKey.tileY, heading: 0 });
62	    await quitter.leave();
63	    await until(() => ledgerOf(host).caches.length === 1, 3000, "the cache");
64	    // The lobby's roster drops a player who quits the running match.
65	    await host.waitFor(() => host.room.state.roster.size === 2);
66	    expect([...host.room.state.roster.values()].map((entry) => entry.seat).sort()).toEqual([seats.host, seats.guest].sort());
67	
68	    // The mirrored fight: both swing on the same frames, so both fall on the same frame. The ledger settles a draw.
69	    await placePair(endpoint, host, guest);
70	    host.fighter.play(brawler(0));
71	    guest.fighter.play(brawler(1));
72	    await grapple(host, guest);
73	    expect(await resultOf(host, guest)).toEqual({ phase: "over", winner: -1, reason: "double-ko" });
74	    await until(() => ledgerOf(host).duels[0]?.phase === "settled", 3000, "the settlement");
75	    expect(ledgerOf(host).duels[0]).toMatchObject({ result: { outcome: "draw" }, settlement: { choice: "none", gold: 0 } });
76	    for (const client of [host, guest]) await client.waitFor(() => client.status()?.mode === "sea" && client.status()?.protection === "draw", 3000);
77	
78	    // At Palm Key the host collects its Sun (sources before caches), then claims the cache's Moon: a full set.
79	    await collectAt(host, endpoint, palmKey, "sun");
80	    await collectAt(host, endpoint, palmKey, "moon");
81	    expect(host.objectives()).toMatchObject({ channelResult: "claimed:moon", rubbings: ["sun", "moon"] });
82	    expect(ledgerOf(host).caches).toEqual([]);
83	
84	    // The claim ends the match.
85	    await host.placeShip(endpoint, CLAIM_SEAT);
86	    await host.holdUntil(HOLD_E, () => host.results() !== undefined, 8000);
87	    await guest.waitFor(() => guest.results() !== undefined, 5000);
88	    const results = host.results()!;
89	    expect(guest.results()).toEqual(results);
90	    expect(results).toMatchObject({ reason: "claim", winnerSeat: seats.host });
91	    const bySeat = [...results.players].sort((a, b) => a.seat - b.seat);
92	    expect(bySeat).toEqual(
93	      [
94	        line(seats.host, { winner: true, rubbingsHeld: 2, collected: 1, cachesClaimed: 1, duelsDrawn: 1, islandsVisited: 1 }),
95	        line(seats.guest, { duelsDrawn: 1 }),
96	        // The quitter's Moon went into the cache: collected, then lost. Placed on Palm Key's dock tile, it never moored there.
97	        line(seats.quitter, { left: true, collected: 1, lost: 1, islandsVisited: 1 }),
98	      ].sort((a, b) => a.seat - b.seat),
99	    );
100	    // The winner's line comes first.
101	    expect(results.players[0]!.seat).toBe(seats.host);
102	  }, 60_000);
103	});
